node -e "
const thanksgiving = 1795651200.0;
const existing = 1788269400.0;
const diff = thanksgiving - existing;
const newTs = thanksgiving + diff;
console.log('Existing reminder: ', existing);
console.log('Thanksgiving 2026: ', thanksgiving);
console.log('Difference:        ', diff, 'seconds (' + (diff/86400).toFixed(2) + ' days)');
console.log('New timestamp:     ', newTs);
console.log('Existing date:     ', new Date(existing * 1000).toUTCString());
console.log('New reminder date: ', new Date(newTs * 1000).toUTCString());
"

